    ["Whose memories"] = "Чьи воспоминания",
    ["Invalid Mature content settings."] = "Недопустимые настройки контента для взрослых.",
    ["Your message was not sent. Open the text box again and retype it."] = "Ваше сообщение не отправлено. Откройте текстовое поле снова и введите его ещё раз.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Недоступны: {models}. См. заметки о Local AI, раздел «Добавление своей модели».",
    ["an embedding model, not a chat model"] = "модель эмбеддингов, а не чат-модель",
    ["could not be read"] = "не удалось прочитать",
    ["file not found"] = "файл не найден",
    ["not a valid GGUF file"] = "не является допустимым файлом GGUF",
    ["{name} (custom)"] = "{name} (пользовательская)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Подготовка {name}: ожидание подключения службы бесед…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Подготовка {name}: ожидание загрузки голосовой модели…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Подготовка {name}: ожидание открытия соединения для бесед…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Подготовка {name}: ожидание, пока игра разместит персонажа…",
    ["Preparing {name}: waiting for the memory service…"] = "Подготовка {name}: ожидание службы памяти…",
    ["Preparing {count} more companions…"] = "Подготовка остальных напарников: {count}…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "Служба бесед не ответила. Подождите немного и пригласите снова.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "Голосовую модель не удалось загрузить. Проверьте голос в настройках или выберите другой и пригласите снова.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Служба памяти не ответила. Проверьте подключение и пригласите снова.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "Соединение для бесед не открылось. Проверьте подключение и пригласите снова.",
    ["Calls are not available during combat."] = "Звонки недоступны во время боя.",
    ["Calls are not available right now."] = "Звонки сейчас недоступны.",
    ["Holocall ended: combat started."] = "Голозвонок завершён: начался бой.",
    ["Holocall with {name} ended."] = "Голозвонок с {name} завершён.",
    ["Live holocall picture"] = "Живое изображение в голозвонке",
    ["Live picture unavailable. The call continues with the portrait."] = "Живое изображение недоступно. Звонок продолжится с портретом.",
    ["This contact cannot take a holocall."] = "Этот контакт не может принять голозвонок.",
    ["You are already on a call."] = "Вы уже в звонке.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "Когда начинается бой, ближайший напарник коротко комментирует, и ещё раз — после него.\n\nПосле боя — десятиминутная пауза. Разговоры и сюжетные сцены важнее. Загрузка сохранения сбрасывает паузу.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Попросите напарника отвезти вас к выбранной на карте метке.\n\nСядьте на пассажирское место, когда он будет готов.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Авто: следует за завершённой встречей в этом сохранении.\n\nДружеский: говорит с такой же близостью.\n\nОбычный: сохраняет её привычную манеру.\n\nЭто не значит, что отношения продолжаются.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Авто: следует за отношениями в этом сохранении.\n\nРомантический: обращается к V как к партнёру.\n\nОбычный: сохраняет свою привычную манеру.\n\nМеняет только манеру речи, но не игровые решения.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "Звук по Bluetooth приходит с небольшой задержкой, поэтому губы и субтитры могут опережать голос. Эта настройка придерживает их, чтобы совпасть с голосом, для всех голосов.\n\nАвто: 150 ms, пока Windows воспроизводит звук через Bluetooth, иначе ничего. Выберите значение, если ваша гарнитура быстрее или медленнее.\n\nВ собственных репликах игры такая же задержка, и она не исправляется.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate."] = "Меняет только меню и уведомления этого мода.\n\nГолоса персонажей и язык, на котором вы говорите, настраиваются отдельно.",
    ["Characters sometimes ask about something you said, pick up something from earlier or share a thought that invites an answer.\n\nNow and then, never on every reply, and never while you are leaving, giving an order or fighting."] = "Персонажи иногда спрашивают о том, что вы сказали, вспоминают что-то из прошлого или делятся мыслью, на которую хочется ответить.\n\nИзредка, не в каждом ответе, и никогда, пока вы уходите, отдаёте приказ или сражаетесь.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "История чата сохраняется между запусками игры.\n\nУдаление воспоминаний о персонаже также удаляет его сохранённые сообщения чата и черновики. Удаление всех воспоминаний очищает все сохранённые чаты.",
    ["Cinematic: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nThe Subtitles switch turns both off."] = "Кинематографические: обычные субтитры диалогов игры.\n\nНад говорящим: над напарником, который говорит.\n\nПереключатель «Субтитры» отключает оба варианта.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "Напарники комментируют, когда вы закончили собирать добычу в мире. Перемещения в хранилище проходят без комментариев.\n\nОбычные комментарии появляются раз в десять минут; новое легендарное снаряжение имеет собственную двухминутную паузу.\n\nПодборы во время боя объединяются в один комментарий в конце боя.",
    ["Companions gesture while they speak longer replies and nod while you talk, with the game’s own animations in their usual stance.\n\nThey stop at once when anyone moves or a fight starts."] = "Напарники жестикулируют, когда говорят длинные ответы, и кивают, пока вы говорите, используя анимации игры в их обычной позе.\n\nОни сразу перестают, если кто-то двигается или начинается бой.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. Each character decides when; it stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Напарники время от времени делают паузы, запинаются, смеются или вздыхают — в зависимости от характера. Каждый персонаж сам решает, когда; это случается редко.\n\nOmniVoice умеет озвучивать смех и вздохи; остальные голоса добавляют только паузы.\n\nНедоступно с облачным голосом Convai: его выбор выключает эту функцию, а её включение переключает голос на Pocket.",
    ["Copy your free key from Mistral first (signing up there needs phone verification). It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder. Mistral allows about one message a second and about 5,000 turns a day. It sets its own monthly cap, estimated at about 150,000 turns."] = "Сначала скопируйте бесплатный ключ из Mistral (регистрация требует подтверждения телефона). Он один раз считывается из буфера обмена, проверяется в Mistral и сохраняется на этом компьютере.\n\nТакже его можно сохранить в файле player-mistral-key.txt в папке службы бесед. Mistral позволяет около одного сообщения в секунду и около 5 000 реплик в день. Месячный лимит задаёт сам Mistral, по оценке около 150 000 реплик.",
    ["Copy your key from Inworld first. It is read from the clipboard once, checked with Inworld and saved on this computer.\n\nYou can also save it in player-inworld-key.txt in the conversation service folder. It is used only for the Inworld voice."] = "Сначала скопируйте ключ из Inworld. Он один раз считывается из буфера обмена, проверяется в Inworld и сохраняется на этом компьютере.\n\nТакже его можно сохранить в файле player-inworld-key.txt в папке службы бесед. Он используется только для голоса Inworld.",
    ["Custom models are ones you added; they join the default choice by size."] = "Добавленные вами модели участвуют в выборе по умолчанию по размеру.",
    ["Each character marks its own feelings as it speaks, so the face changes at that word instead of being guessed from the text. Subtle, set by personality, only where a feeling really shifts.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Каждый персонаж отмечает свои чувства по ходу речи, поэтому мимика меняется на нужном слове, а не угадывается по тексту. Тонко, зависит от характера и только там, где чувство действительно меняется.\n\nНедоступно с облачным голосом Convai: его выбор выключает эту функцию, а её включение переключает голос на Pocket.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Только глаза: голова неподвижна, двигаются только глаза.\n\nОт слабого до сильного: голова всё больше поворачивается к вам.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups (joining steps, dismissals, driving instructions, results of companion actions), writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nPreparation progress, joined notices, failures and replies to Stop trip stay visible when it is off."] = "Для тестов и отчётов об ошибках; в обычной игре оставьте выключенным.\n\nПоказывает служебные всплывающие окна (шаги присоединения, уходы из группы, указания по вождению, результаты действий напарников), записывает трассу движения в рабочую папку мода, пишет в журнал решения о жестах и добавляется в отчёты поддержки.\n\nХод подготовки, уведомления о присоединении, ошибки и ответы на «Остановить» остаются видимыми и при выключенной опции.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "«Удалить все воспоминания» применяется к этим персонажам.\n\nПросмотр каталога или приглашение напарника не добавляет никого в этот счётчик.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "Члены банд, офицеры NCPD, охранники, рипердоки, продавцы, бармены и прохожие отвечают в духе своей среды.\n\nОни не знают вашей истории и забывают вас после загрузки сохранения, кроме продавцов, к которым вы возвращаетесь.\n\nИменованные персонажи не затрагиваются.",
    ["Talk to story characters"] = "Разговоры с персонажами сюжета",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand. They use their own voice and memory, and their face follows what they say.\n\nNothing else about them changes: they do not turn, move, gesture or follow. They do not answer during scenes, quest conversations, fights or rides.\n\nTakes effect after you reload your save."] = "Именованные персонажи самой игры, например Judy, Jackie, Panam и Rogue, отвечают, когда вы к ним обращаетесь там, где они стоят. Они используют собственный голос и память, а их лицо следует за тем, что они говорят.\n\nБольше ничего в них не меняется: они не поворачиваются, не двигаются, не жестикулируют и не следуют за вами. Во время сцен, сюжетных разговоров, боёв или поездок они не отвечают.\n\nВступает в силу после загрузки сохранения.",
    ["{name} is busy right now."] = "{name} сейчас не может говорить.",
    ["Gets a conversation ready when you look at, approach or have just talked to a character, so they answer without a wait. Paused in combat and scenes.\n\nLimits: two characters ready at once, a new one every 3 s, released after 40 s unused. A crowd never adds up."] = "Заранее готовит разговор, когда вы смотрите на персонажа, подходите к нему или только что с ним говорили, поэтому он отвечает без ожидания. Приостанавливается в бою и сценах.\n\nПределы: два персонажа одновременно, новый — каждые 3 с, освобождается через 40 с без использования. Толпа не увеличивает этот счётчик.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Если персонаж перестаёт отвечать, голос пропадает или появляется ошибка: выберите «Сформировать отчёт» и отправьте разработчику указанный в нём файл с кратким описанием того, что вы делали.\n\nЖурналы, перечисленные ниже, показывают, что пошло не так.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Приглашённые персонажи готовятся сразу. Их воспоминания начинаются, когда вы действительно заговорите с ними.\n\nОдна личность игрока используется во всех сохранениях и не меняется после удаления воспоминаний.\n\nТекущий контекст игры описывает загруженный мир.",
    ["Inworld · Cloud voice"] = "Inworld · Облачный голос",
    ["Inworld · needs key"] = "Inworld · нужен ключ",
    ["Needs Local AI."] = "Нужен Local AI.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Найдены только модели для взрослых. Включите Контент для взрослых.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Нельзя: секс с несовершеннолетними, без согласия, о реальных людях, ненависть, инструкции по оружию и наркотикам. Запрет для детей проверяется.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Выкл.: ответы только текстом, голос не создаётся.\n\nЕсли выключены и субтитры, автоматические реакции остаются без звука.",
    ["Pocket: the lightest, runs on your CPU, starts speaking in about 0.2 s.\n\nOmniVoice: richer, especially on harder voices. Needs a capable GPU and the OmniVoice pack (greyed out until it is installed); the higher tiers start in 1 to 2.5 s.\n\nVoxtral: each companion’s own voice from the cloud, with your own Mistral key, English only. It loads no local voice model.\n\nConvai: its own cloud voice. A voice that cannot run is replaced by a simpler one, with one notice."] = "Pocket: самый лёгкий, работает на процессоре, начинает говорить примерно через 0,2 с.\n\nOmniVoice: богаче, особенно на сложных голосах. Нужна мощная видеокарта и пакет OmniVoice (неактивен, пока пакет не установлен); старшие уровни начинают за 1–2,5 с.\n\nVoxtral: собственный голос каждого напарника из облака, с вашим ключом Mistral, только английский. Локальная модель голоса не загружается.\n\nConvai: собственный облачный голос. Голос, который не может работать, заменяется более простым, с одним уведомлением.",
    ["Right after the game’s own dialogue with a character, they know its last few lines, including your chosen replies and your phone calls with them.\n\nOnly the last few minutes count, and none of it is saved to memory."] = "Сразу после собственного диалога игры с персонажем он знает его последние реплики, включая ваши выбранные ответы и телефонные разговоры с ним.\n\nУчитываются только последние несколько минут, и ничего из этого не сохраняется в воспоминания.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Посмотрите, что помнит каждый персонаж, и сотрите воспоминания одного или всех.\n\nВоспоминания сохраняются между сохранениями.",
    ["Shows companion replies as text.\n\nWith Voice playback off as well, automatic reactions stay silent."] = "Показывает ответы напарников текстом.\n\nЕсли озвучивание ответов тоже выключено, автоматические реакции остаются без звука.",
    ["Shows the character live in a holocall instead of their portrait.\n\nIf she cannot be shown, the call goes on with the portrait."] = "Показывает персонажа в голозвонке вживую вместо портрета.\n\nЕсли её нельзя показать, звонок продолжается с портретом.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+), Local AI only."] = "Нецензурная лексика, жестокость, наркотики и, между взрослыми по согласию, флирт и секс. Только 18+, только Local AI.",
    ["Talk in any language; each character answers in yours.\n\nA separate multilingual copy of each character is used, so what they remember from these talks stays apart from your English ones. Forgetting a character clears both.\n\nPocket and Voxtral speak English only, so this switches the voice to OmniVoice · Balanced, or to Convai · Cloud voice without the OmniVoice pack. Without the pack, Natural speech and Expressive emotions turn off."] = "Говорите на любом языке; каждый персонаж отвечает на вашем языке.\n\nДля каждого персонажа используется отдельная многоязычная копия, поэтому его воспоминания из этих бесед отделены от английских. Удаление воспоминаний персонажа очищает обе.\n\nPocket и Voxtral говорят только по-английски, поэтому эта опция переключает голос на OmniVoice · Баланс или на Convai · Облачный голос без пакета OmniVoice. Без пакета Естественная речь и Выразительные эмоции выключаются.",
    ["Turning it on also selects Local AI, the largest uncensored model that fits and a local voice instead of a cloud one. Turning it off restores your choices."] = "Включение выбирает Local AI, крупнейшую подходящую модель без цензуры и локальный голос вместо облачного. Выключение возвращает выбор.",
    ["Use it if companions seem to look above or below your eyes."] = "Включите, если напарники как будто смотрят выше или ниже ваших глаз.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Облако Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · нужен ключ Mistral",
    ["{name} (custom · too large)"] = "{name} (пользовательская · велика)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (своя, {size} GB, нужно {need} GB)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (пользовательская, {size} GB, слишком велика для видеокарты)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Удалить воспоминания о вас у всех персонажей, с которыми вы общались.\n\nВаш идентификатор игрока сохранится. Сначала — подтверждение.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Сохраните файл отчёта, который можно отправить разработчику.\n\nКлючи API, токены, идентификаторы, звук с микрофона и текст бесед не включаются. Без службы бесед создаётся более короткий отчёт из файлов, которые может прочитать игра.",
    ["The Mature pack’s uncensored models give the full effect; standard models mostly refuse sex. Pack: installed."] = "Модели без цензуры из Mature pack дают полный эффект; обычные чаще отказывают в сексе. Пакет: установлен.",
    ["The Mature pack’s uncensored models give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Модели без цензуры из Mature pack дают полный эффект; обычные чаще отказывают в сексе. Пакет: не установлен (необязательно, страница мода на Hugging Face).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Без выбора Local AI грузит самую большую модель, что влезет в видеопамять.\n\nОдна модель за раз; смена при следующей загрузке. Пропавшая, слишком большая или сбойная модель заменяется самой большой подходящей, с уведомлением.",
    ["Body gestures"] = "Жесты",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai не принял ваш API-ключ. Проверьте его в меню Настройки > Поставщик бесед.",
    ["Local AI could not start, so a cloud provider is used. Check Local AI in Settings > Conversation provider."] = "Local AI не удалось запустить, поэтому используется облачный провайдер. Проверьте Local AI в меню Настройки > Поставщик бесед.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Local AI не удалось запустить. Проверьте Local AI в меню Настройки > Поставщик бесед.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral не принял ваш ключ. Проверьте его в меню Настройки > Поставщик бесед.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Ключа Mistral пока нет, поэтому используется Convai. Добавьте свой ключ в меню Настройки > Поставщик бесед.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Нужен ключ Mistral (добавьте его в Настройки > Поставщик бесед)",
    ["Requires an Inworld key (add it in Settings > Development)"] = "Нужен ключ Inworld (добавьте его в Настройки > Разработка)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Для бесед с напарниками пока нужен Convai. Установите в строке Поставщик бесед значение Convai (бесплатный тариф) в меню Настройки > Поставщик бесед или введите сообщение вручную.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider."] = "Достигнут лимит бесед. Попробуйте позже или добавьте бесплатный ключ Mistral и выберите Mistral как поставщика бесед в меню Настройки > Поставщик бесед.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Ваш API-ключ Convai достиг лимита тарифа. Попробуйте позже или добавьте другой ключ в меню Настройки > Поставщик бесед.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Mistral (free, with your own free key) allows about 5,000 turns a day. Local AI is unlimited and runs on your PC."] = "Вы исчерпали сегодняшний бесплатный лимит Convai. Он обновится завтра. Чтобы продолжить прямо сейчас, выберите другого поставщика бесед в меню Настройки > Поставщик бесед. Mistral (бесплатно, с собственным бесплатным ключом) позволяет около 5 000 реплик в день. Local AI без лимита и работает на вашем ПК.",
    ["Today’s {limit} Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Лимит {limit} Convai исчерпан.\nMistral (бесплатно, ~5 000/день) или Local AI (без лимита).",
    ["Today’s Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Лимит Convai исчерпан.\nMistral (бесплатно, ~5 000/день) или Local AI (без лимита).",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral or Local as the conversation provider in the settings."] = "Convai сейчас отвечает, поэтому эти изменения пока не действуют. Выберите Mistral или Local AI в настройках как поставщика бесед.",
    ["Edit a character’s bio, speaking style, speaking rules and memories in your browser.\n\nWorks with Mistral and Local, not Convai. Changes apply from the next reply."] = "Измените биографию персонажа, манеру речи, правила речи и воспоминания в браузере.\n\nРаботает с Mistral и Local AI, но не с Convai. Изменения применяются со следующего ответа.",
    ["Your changes work with Mistral and Local. They do not apply to Convai."] = "Ваши изменения работают с Mistral и Local AI. На Convai они не действуют.",
    ["Choosing a cloud provider turns it off."] = "Облачный провайдер выключает её.",
    ["Inworld always speaks with emotion, whatever this says."] = "Inworld всегда говорит с эмоциями, независимо от этой настройки.",
    ["Inworld can voice laughs and sighs too."] = "Inworld тоже умеет озвучивать смех и вздохи.",
    ["Inworld speaks English only as well."] = "Inworld тоже говорит только по-английски.",
    ["Inworld: the same with your own Inworld key, and it also speaks with emotion."] = "Inworld: то же самое с вашим собственным ключом Inworld, и он также говорит с эмоциями.",
    ["Paste"] = "Вставить",
    ["no Omni pack"] = "нет пакета Omni",
    ["Add your Convai API key below to see and buy a plan."] = "Чтобы увидеть планы и купить один из них, добавьте ниже API-ключ Convai.",
    ["Add your Convai API key first."] = "Сначала добавьте API-ключ Convai.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Сначала добавьте API-ключ Convai: скопируйте его, затем выберите «Вставить» в строке «API-ключ Convai».",
    ["Asking Convai for the payment page…"] = "Запрос страницы оплаты у Convai…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Convai проверит, какой план сейчас у вашего ключа. После оплаты это может занять около 15 секунд.",
    ["Billed every month."] = "Списывается каждый месяц.",
    ["Billed once a year."] = "Списывается раз в год.",
    ["Buy"] = "Купить",
    ["Check"] = "Проверить",
    ["Check my plan"] = "Проверить мой план",
    ["Checking your plan…"] = "Проверка плана…",
    ["Choose Check my plan to ask Convai."] = "Выберите «Проверить мой план», чтобы спросить Convai.",
    ["Contacting Convai…"] = "Связь с Convai…",
    ["Convai could not start the payment. Try again later."] = "Convai не удалось начать оплату. Повторите попытку позже.",
    ["Convai did not accept your API key."] = "Convai не приняло ваш API-ключ.",
    ["Convai does not show a paid plan for your key yet."] = "Convai пока не показывает платный план для вашего ключа.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "Convai пока не подтвердило ваш план. Проверьте его в разделе «Настройки > Платный уровень Convai».",
    ["Convai paid tier"] = "Платный уровень Convai",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "Страница оплаты Convai открыта в браузере. Ваш план активируется примерно через 15 секунд после оплаты.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "Служба оплаты Convai не ответила. Попробуйте ещё раз через минуту.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Планы Convai для этого мода: больше бесед Convai на вашем собственном API-ключе Convai. Откроется страница с планами и их ценами.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Беседы с выбранным поставщиком «API-ключ Convai» используют этот план.",
    ["Get your Convai API key"] = "Получить API-ключ Convai",
    ["Manage or cancel plan"] = "Управлять планом или отменить",
    ["Free"] = "Бесплатно",
    ["Gamer, monthly"] = "Gamer, ежемесячно",
    ["Gamer, yearly"] = "Gamer, ежегодно",
    ["Gamer Pro, monthly"] = "Gamer Pro, ежемесячно",
    ["Gamer Pro, yearly"] = "Gamer Pro, ежегодно",
    ["Current plan"] = "Текущий план",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Это ваш текущий план. Чтобы изменить или отменить его, выберите ниже «Управлять планом или отменить».",
    ["No key added"] = "Ключ не добавлен",
    ["Not checked yet"] = "Ещё не проверялось",
    ["Opened in your browser."] = "Открыто в браузере.",
    ["Opening the page in your browser…"] = "Открываем страницу в браузере…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Открывает страницу оплаты Convai (Stripe) в браузере. Вы платите Convai напрямую; мод никогда не видит вашу карту. Ваш план активируется примерно через 15 секунд после оплаты, и беседы затем используют ваш API-ключ Convai.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Открывает convai.com в браузере. Войдите или создайте бесплатный аккаунт, скопируйте свой API-ключ, затем вернитесь и выберите «Вставить» ниже.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Открывает страницу оплаты Convai в браузере. Войдите в тот же аккаунт Convai, чтобы изменить или отменить план.",
    ["Plans"] = "Планы",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Планы, которые Convai создало для этого мода. Они дают вашему собственному API-ключу Convai больше бесед; бесплатный уровень остаётся прежним.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Цены указаны в долларах США. Отменить подписку можно в любой момент на странице оплаты Convai.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "Служба бесед не запущена, поэтому планы показать нельзя. Перезапустите игру.",
    ["This key has no paid plan. Choose a plan below."] = "У этого ключа нет платного плана. Выберите план ниже.",
    ["Your Convai plan"] = "Ваш план Convai",
    ["Your Convai plan is active."] = "Ваш план Convai активен.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Ваш план Convai активен. Выберите «API-ключ Convai» в разделе «Настройки > Поставщик бесед».",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Ваш план Convai активен. Беседы теперь используют ваш API-ключ Convai.",
    ["Your browser could not be opened."] = "Не удалось открыть браузер.",
    ["Your plan could not be read right now. Try again in a moment."] = "Сейчас не удалось прочитать план. Попробуйте ещё раз через минуту.",
    ["{count} Convai interactions a month."] = "{count} взаимодействий Convai в месяц.",
    ["{plan}, {price} a month"] = "{plan}, {price} в месяц",
    ["{plan}, {price} a year"] = "{plan}, {price} в год",
    ["Sign in with Convai"] = "Войти через Convai",
    ["Sign in"] = "Войти",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Открывает страницу входа Convai в браузере.\n\nВойдите или создайте бесплатный аккаунт: ваш API-ключ Convai сохранится на этом компьютере так же, как при «Вставить». У вас есть пять минут.",
    ["Opening Convai’s sign-in page in your browser…"] = "Открываем страницу входа Convai в браузере…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Войдите на странице Convai в браузере. Когда вы закончите, ключ сохранится здесь.",
    ["Signed in. Your Convai API key is saved."] = "Вход выполнен. Ваш API-ключ Convai сохранён.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "Вход занял слишком много времени. Выберите «Войти через Convai», чтобы попробовать снова.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "Вход не был завершён. Попробуйте снова или скопируйте ключ на convai.com и выберите «Вставить».",
    ["Choose one of the listed voices for V."] = "Выберите один из доступных голосов для V.",
    ["Pocket · On your PC"] = "Pocket · На вашем ПК",
    ["V’s voice engine"] = "Голосовой движок V",
    ["When you type a line, V says it out loud too, in the male or female V voice that matches yours. Push-to-talk is never replayed.\n\nV speaks first, then the companion answers. A slow V line is skipped, so the reply is never delayed. The line always shows as a subtitle.\n\nThe voice that speaks it is chosen in the next row."] = "Когда вы печатаете реплику, V произносит её вслух мужским или женским голосом V, как у вашего персонажа. Ввод через push-to-talk никогда не воспроизводится повторно.\n\nV говорит первым, затем отвечает напарник. Медленная реплика V пропускается, поэтому ответ не задерживается. Реплика всегда отображается в виде субтитра.\n\nГолос, которым она произносится, выбирается в следующей строке.",
    ["Pocket: runs on your processor and starts in about 0.2 s. If the companions use another voice, it loads its own small voice model just for V.\n\nVoxtral: made in the cloud with your Mistral key, so nothing loads on your PC. Starts in about a second. English only, and not with Mature content on.\n\nWhichever you pick, a line that is not ready in time is skipped."] = "Pocket: работает на процессоре и начинает примерно через 0,2 с. Если напарники используют другой голос, он загружает собственную небольшую модель голоса только для V.\n\nVoxtral: генерируется в облаке с вашим ключом Mistral, поэтому на ПК ничего не загружается. Начинает примерно через секунду. Только английский, и недоступен при включённом контенте для взрослых.\n\nЧто бы вы ни выбрали, реплика, которая не готова вовремя, пропускается.",
    ["Johnny in your head"] = "Johnny в вашей голове",
    ["Johnny Silverhand answers when you use the talk keys with nobody in front of you, as the voice in V’s head. He knows your jobs and your story so far, and what he thinks of you follows it.\n\nOnly while the story has him in V’s head. He stays quiet during scenes, calls, dialogue choices and fights, and when the game gives him a line."] = "Johnny Silverhand отвечает, когда вы пользуетесь клавишами разговора, а рядом никого нет, голосом в голове V. Он знает ваши задания и историю до этого момента, и то, как он к вам относится, меняется соответственно.\n\nТолько пока сюжет держит его в голове V. Он молчит во время сцен, звонков, выбора реплик и боёв, а также когда игра даёт ему реплику.",
    ["Johnny’s standing"] = "Отношения с Johnny",
    ["Where you and Johnny stand in this save’s story. It follows what you have been through together, such as Alt, the oil fields, Rogue and the reunion concert.\n\nRead from your save; nothing is stored."] = "Каковы отношения между вами и Johnny в истории этого сохранения. Учитываются общие события, например Alt, нефтяные поля, Rogue и концерт воссоединения.\n\nСчитывается из вашего сохранения; ничего не записывается.",
    ["Not in your head yet"] = "Пока не в голове",
    ["Wary"] = "Настороженность",
    ["Grudging respect"] = "Неохотное уважение",
    ["Friends"] = "Друзья",
    ["Close friends"] = "Близкие друзья",
    ["Gone after the ending"] = "Пропал после финала",
    ["Johnny speaks up"] = "Johnny подаёт голос",
    ["Rare"] = "Редко",
    ["Normal"] = "Обычно",
    ["Choose how often Johnny speaks up."] = "Выберите, как часто Johnny подаёт голос.",
    ["A pack is one folder too deep. See Help in Settings."] = "Пакет на одну папку глубже. См. Справку в Настройках.",
    ["All files found."] = "Все файлы найдены.",
    ["Browser"] = "Браузер",
    ["Found."] = "Найдено.",
    ["Found: {list}."] = "Найдено: {list}.",
    ["Game version"] = "Версия игры",
    ["Graphics card"] = "Видеокарта",
    ["Internet"] = "Интернет",
    ["Loaded."] = "Загружено.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "Локальный ИИ не удалось запустить. Сформируйте отчёт ниже и отправьте его или выберите другого поставщика бесед.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "Локальный ИИ не нашёл подходящей видеокарты. Нужна карта NVIDIA или AMD с актуальным драйвером. Обновите драйвер или выберите другого поставщика бесед.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Отсутствуют: {files}. Распакуйте архив Scripts в папку Cyberpunk 2077 заново и разрешите замену файлов.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. Файлы, которые создаёт мод, попадают в его папку Overwrite; оставьте их там. Упомяните Mod Organizer 2, когда отправляете отчёт.",
    ["Mod files"] = "Файлы мода",
    ["Mod manager"] = "Менеджер модов",
    ["Moved into place from {folder}: {packs}."] = "Перемещено из {folder}: {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Пакет Локального ИИ не найден. Скачайте его со страницы мода на Hugging Face и распакуйте в папку Cyberpunk 2077 или выберите другого поставщика бесед.",
    ["No problem found. Select a line to see what was checked."] = "Проблем не найдено. Выберите строку, чтобы увидеть, что проверялось.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the Runtime zip straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game."] = "В этом сеансе службы бесед не видно: Runtime отсутствует или не загрузился. Распакуйте архив Runtime прямо в папку Cyberpunk 2077 (не в новую папку), проверьте, что там есть red4ext/plugins/AiNpcCyberpunkMod, и перезапустите игру.",
    ["None found: installed by hand."] = "Не найдено: установлено вручную.",
    ["None installed. They are optional."] = "Ничего не установлено. Они необязательны.",
    ["Not needed: Local AI and the voice run on this PC."] = "Не нужно: Локальный ИИ и голос работают на этом ПК.",
    ["Not used"] = "Не используется",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Не ваш поставщик бесед. Выберите его в меню Настройки > Поставщик бесед.",
    ["Note"] = "Примечание",
    ["OK"] = "OK",
    ["Optional packs"] = "Дополнительные пакеты",
    ["Problem"] = "Проблема",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Найдено проблем: {count}. Выберите строку с пометкой «Проблема», чтобы прочитать, что делать.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "RED4ext не загружен. Установите его с Nexus Mods и перезапустите игру. Он также запускает службу бесед.",
    ["Reached {host}."] = "Связь с {host} установлена.",
    ["Scripts and Runtime"] = "Scripts и Runtime",
    ["Scripts {scripts} and Runtime {runtime} do not match. Download both for the same version and extract them into the Cyberpunk 2077 folder."] = "Версии Scripts {scripts} и Runtime {runtime} не совпадают. Скачайте оба архива одной версии и распакуйте в папку Cyberpunk 2077.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Download the Runtime for the same version and extract it into the Cyberpunk 2077 folder, then restart the game."] = "Служба бесед не ответила на проверку установки, поэтому её Runtime, вероятно, старше этих Scripts. Скачайте Runtime той же версии, распакуйте в папку Cyberpunk 2077 и перезапустите игру.",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} и Runtime {runtime}.",
    ["Setup check"] = "Проверка установки",
    ["Some mod files are missing. Extract the Scripts zip again. See Help in Settings."] = "Не хватает файлов мода. Распакуйте архив Scripts заново. См. Справку в Настройках.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Некоторые файлы пакета не удалось переместить, потому что на их месте уже лежат другие файлы. Распакуйте пакет в папку Cyberpunk 2077 заново и разрешите замену файлов.",
    ["The Runtime is incomplete ({code}). Download it again and extract it into the Cyberpunk 2077 folder, then restart the game."] = "Runtime неполный ({code}). Скачайте его заново, распакуйте в папку Cyberpunk 2077 и перезапустите игру.",
    ["The Scripts and Runtime versions do not match. Install the same version of both."] = "Версии Scripts и Runtime не совпадают. Установите обе одной версии.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "Служба бесед не может подключиться к интернету. См. Справку в Настройках.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "Служба бесед не может подключиться к {host}. Разрешите Node.js в брандмауэре или антивирусе (Windows спросит один раз; выберите «Разрешить доступ»), проверьте подключение к интернету и перезапустите игру.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "Служба бесед не смогла запуститься ({code}). Перезапустите игру. Если это повторится, сформируйте отчёт ниже и отправьте его.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "Служба бесед не запустилась. Установлен ли Runtime? См. Справку в Настройках.",
    ["The game version could not be read."] = "Не удалось определить версию игры.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Этот ПК не может найти {host}. Проверьте подключение к интернету и перезапустите игру.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Откройте r6/logs/redscript_rCURRENT.log. Указанный там мод блокирует скрипты.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware, Audioware or redscript, or a game version other than 2.31, can also cause it."] = "Скрипты этого мода не загрузились. Откройте r6/logs/redscript_rCURRENT.log. Если в ошибке назван другой мод, проблема в нём. Причиной могут быть и отсутствующий или устаревший Codeware, Audioware или redscript, либо версия игры, отличная от 2.31.",
    ["Missing: {names}. Install them and restart the game."] = "Отсутствуют: {names}. Установите их и перезапустите игру.",
    ["Install or update: {names}. Then restart the game."] = "Установите или обновите: {names}. Затем перезапустите игру.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "Codeware слишком старый. Обновите его с Nexus Mods и перезапустите игру.",
    ["Version {version}."] = "Версия {version}.",
    ["Version {version}. The mod is tested on 2.31 only, so some things may not work."] = "Версия {version}. Мод проверен только на версии 2.31, поэтому некоторые вещи могут не работать.",
    ["Vortex. Install the Runtime and the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say."] = "Vortex. Установите Runtime и дополнительные пакеты вручную в папку Cyberpunk 2077, как сказано в шагах установки.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "{name} отсутствует. Установите его с Nexus Mods и перезапустите игру.",
    ["{name}, {memory} GB of video memory."] = "{name}, видеопамять: {memory} ГБ.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} лежит на одну папку глубже, чем нужно, в {folder}. Перезапустите игру, и мод сам переместит файлы на место. Если они останутся там, переместите находящуюся внутри папку red4ext в папку Cyberpunk 2077.",
    ["Add an endpoint URL and a model ID first."] = "Сначала добавьте URL эндпоинта и ID модели.",
    ["Convai: the custom provider is not set up yet"] = "Convai: свой поставщик ещё не настроен",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Скопируйте базовый URL у поставщика, например https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 или http://localhost:11434/v1 (Ollama). Он один раз считывается из буфера обмена и сохраняется на этом компьютере.\n\nhttp:// можно использовать только на этом компьютере и в домашней сети. Также можно указать endpoint=, model= и api-key= в файле player-custom-endpoint.txt в папке службы бесед.\n\nНичего не отправляется, пока вы не выберете этого поставщика или не нажмёте «Проверить связь».",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Сначала скопируйте ID модели у поставщика, например meta-llama/llama-3.1-8b-instruct (OpenRouter) или llama3.2 (Ollama). Он один раз считывается из буфера обмена и сохраняется на этом компьютере.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Сначала скопируйте API-ключ у поставщика. Он один раз считывается из буфера обмена и сохраняется только на этом компьютере. Локальному серверу, например Ollama или LM Studio, ключ обычно не нужен.",
    ["Custom (OpenAI-compatible)"] = "Свой (OpenAI-compatible)",
    ["Custom API key"] = "Свой API-ключ",
    ["Custom endpoint URL"] = "Свой URL эндпоинта",
    ["Custom model ID"] = "Свой ID модели",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Ответы своего поставщика читает местный голос, не облачный голос Convai.",
    ["Custom: key not accepted"] = "Свой: ключ не принят",
    ["Custom: model unavailable"] = "Свой: модель недоступна",
    ["Custom: out of credits"] = "Свой: кончились кредиты",
    ["Custom: rate limited for now"] = "Свой: временно ограничено",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Удаляет сохранённый URL эндпоинта. Свому поставщику он нужен для ответов.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Удаляет сохранённый ключ. Потом ответы своего поставщика запрашиваются без ключа.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Удаляет сохранённый ID модели. Свому поставщику он нужен для ответов.",
    ["Failed"] = "Ошибка",
    ["It answered in {ms} ms."] = "Ответ за {ms} мс.",
    ["It could not be saved."] = "Не удалось сохранить.",
    ["Model ID: {model}"] = "ID модели: {model}",
    ["Only https:// works outside this computer and your home network."] = "Вне этого компьютера и домашней сети работает только https://.",
    ["Paste API key"] = "Вставить API-ключ",
    ["Paste endpoint URL"] = "Вставить URL",
    ["Paste model ID"] = "Вставить ID модели",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Отправляет эндпоинту одно короткое сообщение с сохранённым ID модели и ключом и показывает ответ. Почти не тратит кредиты.",
    ["Test"] = "Тест",
    ["Test connection"] = "Проверить связь",
    ["Testing the connection…"] = "Проверка связи…",
    ["Testing…"] = "Проверка…",
    ["That is too long."] = "Это слишком длинно.",
    ["That was not accepted."] = "Не принято.",
    ["The account is out of credits. Add credits with your provider."] = "На счёте закончились кредиты. Пополните их у поставщика.",
    ["The address must start with https:// or http://."] = "Адрес должен начинаться с https:// или http://.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "Адрес ведёт в другое место. Используйте конечный адрес от поставщика.",
    ["The clipboard does not hold a model ID."] = "В буфере обмена нет ID модели.",
    ["The clipboard does not hold a web address."] = "В буфере обмена нет веб-адреса.",
    ["The clipboard does not hold an API key."] = "В буфере обмена нет API-ключа.",
    ["The clipboard is empty. Copy it first."] = "Буфер обмена пуст. Сначала скопируйте.",
    ["The connection test failed."] = "Проверка связи не удалась.",
    ["The connection works. The endpoint accepted your model and key."] = "Связь работает. Эндпоинт принял вашу модель и ключ.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "Служба бесед не запущена, поэтому проверить ничего нельзя. Перезапустите игру.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Свой ключ не принят. Проверьте его в меню Настройки > Поставщик бесед.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Свой поставщик не ответил. Проверьте адрес в Настройках или попробуйте снова.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Свой поставщик не знает этот ID модели. Проверьте в Настройках.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Свой поставщик не задан, работает Convai. Добавьте URL и ID модели в Настройках.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "Свой поставщик ограничивает запросы. Попробуйте через минутку.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Свой поставщик сообщает: на счёте нет кредитов. Пополните и попробуйте снова.",
    ["The endpoint URL was removed."] = "URL эндпоинта удалён.",
    ["The endpoint answered with no text. Check the model ID."] = "Эндпоинт ответил без текста. Проверьте ID модели.",
    ["The endpoint did not accept your API key."] = "Эндпоинт не принял ваш API-ключ.",
    ["The endpoint did not answer. Check its address."] = "Эндпоинт не ответил. Проверьте адрес.",
    ["The endpoint does not know that model ID."] = "Эндпоинт не знает этот ID модели.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "Эндпоинт ограничивает запросы. Попробуйте через минутку.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "Эндпоинт ограничивает запросы. Подождите около {seconds} сек. и попробуйте снова.",
    ["The endpoint refused the request. Check the model ID and the address."] = "Эндпоинт отклонил запрос. Проверьте ID модели и адрес.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "Эндпоинт сообщил об ошибке на своей стороне. Попробуйте через минутку.",
    ["The endpoint took too long to answer."] = "Эндпоинт слишком долго отвечал.",
    ["The model ID was removed."] = "ID модели удалён.",
    ["The provider said: {detail}"] = "Поставщик ответил: {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Адрес не зашифрован, но на вашем компьютере или в домашней сети это нормально.",
    ["Use the base URL only: no password, query or #."] = "Укажите только базовый URL: без пароля, параметров запроса и #.",
    ["Waiting for the endpoint to answer…"] = "Ожидание ответа эндпоинта…",
    ["Custom: free daily limit reached"] = "Свой: дневной бесплатный лимит исчерпан",
    ["New address saved. Paste your API key again for it."] = "Новый адрес сохранён. Вставьте для него API-ключ ещё раз.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Дневной бесплатный лимит этой модели исчерпан. Сбросится в {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Дневной бесплатный лимит этой модели исчерпан. Попробуйте снова после сброса.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Модель тратит ответ на раздумья. Выберите в Настройках модель без рассуждений.",
    ["A change takes effect after the current reply. No game restart is needed."] = "Изменение вступит в силу после текущего ответа. Перезапуск игры не нужен.",
    ["All"] = "Все",
    ["Also changed: {names}."] = "Также изменено: {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Выберите любого персонажа из списка ниже. Его присутствие в группе не требуется.",
    ["Defaults restored."] = "Значения по умолчанию восстановлены.",
    ["Drag the slider, or press left and right, to turn the page."] = "Перетащите ползунок или нажмите влево и вправо, чтобы переключить страницу.",
    ["How loud the mod’s voices are, for companions, characters and V’s typed lines. 100 is the normal level.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. The game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Насколько громко звучат голоса мода: напарников, персонажей и реплик, которые вы набираете за V. 100 — обычный уровень.\n\nВыше 100 голоса звучат громче, лимитер не даёт им хрипеть. Диалоги и звуки самой игры не меняются.\n\nСледующий ответ использует значение.",
    ["Not available right now."] = "Сейчас недоступно.",
    ["Open Settings to restore its defaults."] = "Откройте настройки, чтобы восстановить значения по умолчанию.",
    ["Page"] = "Страница",
    ["Show only the models whose name starts with this letter."] = "Показывать только модели, название которых начинается с этой буквы.",
    ["Starts with"] = "Начинается с",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Откройте AI NPC Cyberpunk Mod в списке модов.",
    ["The settings could not be saved. Nothing was changed."] = "Не удалось сохранить настройки. Ничего не было изменено.",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Mistral (with your free key, about 5,000 turns a day) or Local AI (unlimited)."] = "Вы уже использовали сегодняшние {limit} реплик. Они вернутся завтра. Чтобы продолжить прямо сейчас, выберите Mistral (с бесплатным ключом, примерно 5 000 реплик в день) или Local AI (без лимита).",
    ["Johnny says something on his own after you meet someone he knows of, finish a job, or a romance moves on. Needs Johnny in your head.\n\nRare: at most twice an hour. Normal: at most six times an hour, never closer than five minutes.\n\nOn the Convai free tier each remark uses one of the day’s turns; remarks never take more than a tenth of them."] = "Johnny сам что-нибудь говорит, когда вы встречаете того, о ком он знает, заканчиваете задание или романтическая линия продвигается. Нужен Johnny в вашей голове.\n\nРедко: не более двух раз в час. Обычно: не более шести раз в час, но не чаще, чем через пять минут.\n\nНа бесплатном тарифе Convai каждая реплика тратит один из сегодняшних ходов; реплики никогда не занимают больше одной десятой всех ходов.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral or Local AI, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Кто пишет ответы ваших напарников. Изменение ждёт, пока ни одна беседа не выполняется.\n\nБесплатный тариф Convai не требует настройки и даёт лучшие ответы. Вариант «Ключ Convai API» использует ваш ключ, а Mistral работает на бесплатном тарифе с вашим бесплатным ключом; память остаётся на этом компьютере.\n\nС Mistral или Local AI облачный голос Convai заменяется локальным голосом. Речь распознаётся на этом компьютере, поэтому голосовой ключ работает.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral uses its free plan with your own free key; memory stays on this computer.\n\nWith Mistral or Local AI, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Кто пишет ответы ваших напарников. Изменение ждёт, пока ни одна беседа не выполняется.\n\nБесплатный тариф Convai не требует настройки и даёт лучшие ответы. Вариант «Ключ Convai API» использует ваш ключ, а Mistral работает на бесплатном тарифе с вашим бесплатным ключом; память остаётся на этом компьютере.\n\nС Mistral или Local AI облачный голос Convai заменяется локальным голосом. Распознавание речи для голосового ключа с ними пока недоступно, поэтому вводите сообщения текстом.",
    ["Privacy"] = "Конфиденциальность",
    ["Send error reports automatically"] = "Автоотправка отчётов об ошибках",
    ["When something in the mod goes wrong, a short report goes to the developer so it can be fixed without asking you for logs. At most five a day.\n\nIt holds the error, the mod and requirement versions, your provider and voice choices, whether Mature content is on, your graphics card, the setup check and the log lines around the error.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name."] = "Если в моде что-то идёт не так, разработчику отправляется короткий отчёт, чтобы ошибку можно было исправить без запроса журналов. Не более пяти в день.\n\nВ нём содержатся сама ошибка, версии мода и его требований, ваш выбор поставщика и голоса, включён ли контент для взрослых, ваша видеокарта, результат проверки настройки и строки журналов вокруг ошибки.\n\nОн никогда не содержит ключей, того, что говорите вы или персонажи, воспоминаний, аудио и имени пользователя Windows.",
    ["Error reports go to the developer automatically. Turn them off in Settings > Privacy."] = "Отчёты об ошибках сами уходят разработчику. Выкл.: Настройки > Конфиденциальность.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "Для «Управления напарниками» нужен Mod Configuration Menu 0.10.5+ или Native Settings UI",
    ["Update Mod Configuration Menu to 0.10.5 or newer to use the Companion Manager"] = "Обновите Mod Configuration Menu до 0.10.5+ для «Управления напарниками»",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI 1.96 or newer. Install one from Nexus Mods, then restart the game."] = "Для «Управления напарниками» нужен Mod Configuration Menu 0.10.5 или новее, либо Native Settings UI 1.96 или новее. Установите один из них с Nexus Mods и перезапустите игру.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer from Nexus Mods, then restart the game."] = "Mod Configuration Menu слишком старый. Обновите его до 0.10.5 или новее с Nexus Mods и перезапустите игру.",
    ["Previous page"] = "Предыдущая страница",
    ["Next page"] = "Следующая страница",
    ["Go"] = "Перейти",
    ["Starts with: {letter}"] = "Начинается с: {letter}",
    ["Characters and party"] = "Персонажи и группа",
    ["Load a save first"] = "Загрузите сохранение",
    ["Inviting characters and managing your party need a loaded game."] = "Приглашать персонажей и управлять группой можно только в загруженной игре.",
}
